command-pattern.pseudocode:
class Light:  # Receiver: 실제 작업 수행
    def on(self): print('on')
    def off(self): print('off')

class LightOnCommand:  # ConcreteCommand
    def __init__(self, light):
        self.light = light
    def execute(self):
        self.light.on()
    def undo(self):
        self.light.off()

class Remote:  # Invoker: 수행자를 모름
    def __init__(self):
        self.history = []
    def press(self, cmd):
        cmd.execute()
        self.history.append(cmd)  # Undo용 이력
    def undo(self):
        if self.history:
            self.history.pop().undo()

remote = Remote()  # Client: 명령 조립
remote.press(LightOnCommand(Light()))
remote.undo()  # 'off'

compaction.pseudocode:
def compact(sstables):
    # 각 SSTable: key -> (timestamp, value)
    latest = {}
    for table in sstables:
        for key, (ts, value) in table.items():
            if key not in latest or ts > latest[key][0]:
                latest[key] = (ts, value)  # 최신 버전만 유지
    out = []
    for key in sorted(latest):  # 키 순 정렬 → 새 SSTable
        ts, value = latest[key]
        if value is TOMBSTONE:
            continue  # 삭제 표시 물리 제거(유예 기간 경과 가정)
        out.append((key, ts, value))
    return out  # 입력 SSTable들은 이후 삭제

competitive-learning.pseudocode:
def competitive_learning(data, k, lr=0.1, epochs=20):
    w = [list(x) for x in random_sample(data, k)]  # 초기 가중치
    for _ in range(epochs):
        for x in data:
            # 경쟁: 입력과 가장 가까운 출력 뉴런이 승자
            j = min(range(k), key=lambda i: dist2(w[i], x))
            # 승자독식: 승자 가중치만 입력 쪽으로 이동
            w[j] = [wi + lr * (xi - wi)
                    for wi, xi in zip(w[j], x)]
    return w  # 각 w[j]는 한 군집의 원형(prototype)

def dist2(a, b):
    return sum((p - q) ** 2 for p, q in zip(a, b))

