computational-graph.pseudocode:
class Node:  # 계산 그래프 노드: 값 + [(부모, 국소 기울기)]
    def __init__(self, value, parents=()):
        self.value, self.parents = value, parents
        self.grad = 0.0

def add(a, b):  # 국소 기울기 1, 1
    return Node(a.value + b.value, [(a, 1.0), (b, 1.0)])

def mul(a, b):  # 국소 기울기: 상대 피연산자 값
    return Node(a.value * b.value,
                [(a, b.value), (b, a.value)])

def backward(out):  # 위상 역순으로 연쇄 법칙 적용
    order, seen = [], set()
    def topo(n):
        if id(n) not in seen:
            seen.add(id(n))
            for p, _ in n.parents:
                topo(p)
            order.append(n)
    topo(out)
    out.grad = 1.0
    for n in reversed(order):
        for p, local in n.parents:
            p.grad += local * n.grad  # 경로별 기울기 누적

conflict-free-replicated-data-type.pseudocode:
class GCounter:  # 상태 기반 증가 전용 카운터
    def __init__(self, node_id, nodes):
        self.id = node_id
        self.p = {n: 0 for n in nodes}  # 노드별 증가량

    def increment(self, k=1):
        self.p[self.id] += k  # 자기 칸만 증가

    def value(self):
        return sum(self.p.values())

    def merge(self, other):  # 교환·결합·멱등 만족
        for n in self.p:
            self.p[n] = max(self.p[n], other.p[n])

connection-pool.pseudocode:
class ConnectionPool:
    def __init__(self, min_size, max_size):
        self.idle = [create_conn() for _ in range(min_size)]
        self.active = 0  # 대여 중인 연결 수
        self.max_size = max_size

    def borrow(self, timeout):
        deadline = now() + timeout
        while True:
            if self.idle:  # 유휴 연결 재사용
                conn = self.idle.pop()
                break
            if self.active < self.max_size:
                conn = create_conn()  # 상한 미만이면 신규 생성
                break
            if now() >= deadline:
                raise PoolExhausted()  # 풀 고갈
            wait_for_release(deadline)
        self.active += 1
        return conn

    def release(self, conn):
        self.active -= 1
        self.idle.append(conn)  # 닫지 않고 풀에 반납
        notify_waiters()

conservative-two-phase-locking.pseudocode:
def conservative_2pl(tx, locks):
    needed = tx.read_set | tx.write_set  # 사전 선언 필요
    while True:
        with locks.mutex:  # 검사·획득을 원자적으로
            if all(locks.can_grant(tx, item)
                   for item in needed):
                for item in needed:  # 한 번에 전부 획득
                    locks.grant(tx, item)
                break
        locks.wait_release()  # 하나도 잡지 않고 대기
    tx.execute()  # 실행 중 추가 잠금 요청 없음
    for item in needed:
        locks.release(tx, item)

consistent-heuristic.pseudocode:
def is_consistent(nodes, edges, h, goals):
    for g in goals:
        if h[g] != 0:  # 목표에서 h = 0
            return False
    for n in nodes:
        for m, cost in edges[n]:  # 후계 m, 간선 비용
            if h[n] > cost + h[m]:  # 삼각부등식 위반
                return False
    return True

content-based-filtering.pseudocode:
def recommend(user_liked, items, vec, top_n=10):
    # vec: 아이템 → TF-IDF·임베딩 벡터
    profile = mean([vec[i] for i in user_liked])
    scores = []
    for i in items:
        if i in user_liked:
            continue  # 이미 본 아이템 제외
        scores.append((cosine(profile, vec[i]), i))
    scores.sort(reverse=True)
    return [i for _, i in scores[:top_n]]

def cosine(a, b):
    return dot(a, b) / (norm(a) * norm(b) + 1e-9)

content-negotiation.pseudocode:
def negotiate(accepts, available):
    # accepts: (미디어 타입, q값) 목록, 예 ('text/html', 1.0)
    best, best_q = None, 0.0
    for mtype, q in accepts:
        for rep in available:  # 서버가 가진 표현들
            # matches는 와일드카드(*/*, text/*) 처리
            if matches(mtype, rep.mtype) and q > best_q:
                best, best_q = rep, q
    if best is None:
        return 406  # Not Acceptable
    return best  # 응답에 Vary: Accept 헤더 포함

context-manager.pseudocode:
class Locked:  # 클래스 기반 컨텍스트 매니저
    def __init__(self, lock):
        self.lock = lock
    def __enter__(self):
        self.lock.acquire()  # 자원 획득
        return self.lock
    def __exit__(self, exc_type, exc, tb):
        self.lock.release()  # 예외가 나도 항상 해제
        return False  # False면 예외를 그대로 전파

# with Locked(lock) as res: work(res) 의 동작을 풀어 쓴 형태
mgr = Locked(lock)
res = mgr.__enter__()
try:
    work(res)
except BaseException as e:
    if not mgr.__exit__(type(e), e, e.__traceback__):
        raise
else:
    mgr.__exit__(None, None, None)

contrastive-learning.pseudocode:
def info_nce(anchors, positives, tau=0.1):
    # anchors[i]·positives[i]는 양성 쌍, 배치 내 나머지는 음성
    n, loss = len(anchors), 0.0
    for i in range(n):
        logits = [cos_sim(anchors[i], positives[j]) / tau
                  for j in range(n)]
        # -log( exp(양성) / Σ exp(전체) )
        loss += logsumexp(logits) - logits[i]
    return loss / n  # 양성은 가깝게, 음성은 멀게 학습

def cos_sim(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (norm(a) * norm(b))

control-flow-flattening.pseudocode:
# 원본: 순차·분기 구조가 그대로 보임
def check(x):
    y = x * 2
    if y > 10:
        return 'big'
    return 'small'

# 평탄화: 모든 블록이 한 디스패처 루프의 case
def check_flat(x):
    state = 1  # 다음에 실행할 블록 번호
    while True:  # 디스패처 루프
        if state == 1:
            y = x * 2
            state = 2
        elif state == 2:
            state = 3 if y > 10 else 4  # 분기도 상태 갱신으로
        elif state == 3:
            return 'big'
        elif state == 4:
            return 'small'

coroutine.pseudocode:
def worker(name, n):
    for i in range(n):
        print(name, i)
        yield  # 자발적 양보: 상태 보존 후 중단

def run(tasks):  # 단순 라운드 로빈 이벤트 루프
    queue = list(tasks)
    while queue:
        t = queue.pop(0)
        try:
            next(t)  # 중단 지점부터 재개
            queue.append(t)
        except StopIteration:
            pass  # 코루틴 종료

run([worker('A', 2), worker('B', 2)])  # A0 B0 A1 B1

count-min-sketch.pseudocode:
class CountMin:
    def __init__(self, eps, delta):
        self.w = ceil(E / eps)  # 열 수 → 오차 ε·N 이내
        self.d = ceil(log(1 / delta))  # 행 수 → 확률 1-δ 보장
        self.t = [[0] * self.w for _ in range(self.d)]

    def _col(self, i, x):  # 행마다 독립 해시 함수
        return hash_i(i, x) % self.w

    def add(self, x, c=1):  # 갱신 O(d)
        for i in range(self.d):
            self.t[i][self._col(i, x)] += c

    def estimate(self, x):  # 조회 O(d): 최솟값 반환
        return min(self.t[i][self._col(i, x)]
                   for i in range(self.d))  # 과대추정만 발생
